<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api, hasRole, newRequestId } from '../api'
import { errorText } from '../candidates/types'
type Person = {name:string;employeeNo:string;phone:string;department:string;team:string;professionalDirection:string;educationMajor:string;position:string;trainingStartDate:string|null}
type Entry = {source:string;id:number;title:string;course:string;date:string;score:number|null;totalScore:number;passed:boolean|null;status:string;recordedBy:string;recordedAt:string;note:string}
type Profile = {person:Person;grades:Entry[];months:{month:string;count:number;averagePercent:number;passRate:number;practiceSeconds:number}[];practiceSeconds:number}
const id = String(useRoute().params.id), profile = ref<Profile|null>(null), error = ref(''), message = ref(''), busy = ref(false)
const fields = ref({professionalDirection:'',educationMajor:'',position:'',trainingStartDate:''})
const canEdit = hasRole('SYSTEM_ADMIN','TRAINING_ADMIN')
const manual = ref({title:'',course:'',score:0,totalScore:100,passScore:90,examDate:new Date(Date.now() + 8*3600000).toISOString().slice(0,10),note:'',requestId:newRequestId()})
async function load() { try { profile.value = await api('/api/profiles/'+id); if(profile.value) { const p=profile.value.person; fields.value={professionalDirection:p.professionalDirection||'',educationMajor:p.educationMajor||'',position:p.position||'',trainingStartDate:p.trainingStartDate||''} } } catch(e) {error.value=errorText(e)} }
async function save() {busy.value=true; error.value='';try{profile.value=await api('/api/profiles/'+id,{method:'PUT',body:JSON.stringify({...fields.value,trainingStartDate:fields.value.trainingStartDate||null})});message.value='档案已保存'}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function add() { if(!window.confirm('确认录入这条人工补考成绩？记录将保留录入人、时间及依据。'))return; busy.value=true;error.value='';try{await api('/api/profiles/'+id+'/manual-grades',{method:'POST',body:JSON.stringify(manual.value)});manual.value.requestId=newRequestId();manual.value.title='';manual.value.note='';await load();message.value='补考成绩已录入'}catch(e){error.value=errorText(e)}finally{busy.value=false} }
onMounted(load)
</script>
<template>
<div class="page-head"><div><h1>{{ profile?.person.name || '人员' }}的培训档案</h1><p>历次考试自动归档，人工补考单独标明来源。</p></div><RouterLink class="secondary-button" to="/users">返回人员列表</RouterLink></div>
<p v-if="error" class="notice error" role="alert">{{ error }} <button class="link-button" @click="load">重新加载</button></p><p v-if="message" class="notice" role="status">{{ message }}</p>
<template v-if="profile"><article class="panel"><h2>个人资料</h2><p>{{ profile.person.employeeNo }} · {{ profile.person.department || '未填部门' }} · {{ profile.person.team || '未填班组' }} · {{ profile.person.phone || '未填手机号' }}</p><form class="profile-form" @submit.prevent="save"><label>专业方向<input v-model="fields.professionalDirection" :disabled="!canEdit" maxlength="100"></label><label>所学专业<input v-model="fields.educationMajor" :disabled="!canEdit" maxlength="100"></label><label>岗位<input v-model="fields.position" :disabled="!canEdit" maxlength="100"></label><label>培训开始日期<input v-model="fields.trainingStartDate" :disabled="!canEdit" type="date"></label><button v-if="canEdit" class="primary-button" :disabled="busy">保存档案</button></form></article>
<article class="panel"><h2>月度学习分析</h2><p class="hint">北京时间，以考试日期归月；统计所有已判卷答卷及人工补考记录，补考单独计次，取消考试不计入。均分按百分制折算。累计有效练习 {{ (profile.practiceSeconds/60).toFixed(1) }} 分钟。</p><div class="table-wrap"><table><thead><tr><th>月份</th><th>成绩次数</th><th>平均分（百分制）</th><th>及格率</th><th>有效练习（分钟）</th></tr></thead><tbody><tr v-for="m in profile.months" :key="m.month"><td>{{m.month}}</td><td>{{m.count}}</td><td>{{m.count?m.averagePercent.toFixed(1):'—'}}</td><td>{{m.count?m.passRate.toFixed(1)+'%':'—'}}</td><td>{{(m.practiceSeconds/60).toFixed(1)}}</td></tr></tbody></table></div><p v-if="!profile.months.length">尚无考试或练习记录</p></article>
<details v-if="canEdit" class="panel"><summary>录入人工补考成绩</summary><p class="hint">请填写录入依据；此记录进入档案和月分析，不改变系统答卷，也不会销号。</p><form class="profile-form" @submit.prevent="add"><label>考试名称<input v-model="manual.title" required maxlength="160"></label><label>课程<input v-model="manual.course" required maxlength="100"></label><label>考试日期<input v-model="manual.examDate" type="date" required></label><label>得分<input v-model.number="manual.score" type="number" min="0" :max="manual.totalScore" required></label><label>总分<input v-model.number="manual.totalScore" type="number" min="1" required></label><label>及格分<input v-model.number="manual.passScore" type="number" min="0" :max="manual.totalScore" required></label><label class="wide">录入依据 / 说明<textarea v-model="manual.note" required maxlength="1000" rows="3"></textarea></label><button class="primary-button" :disabled="busy">保存补考成绩</button></form></details>
<article class="panel"><h2>历次成绩</h2><div class="table-wrap"><table><thead><tr><th>考试 / 课程</th><th>日期</th><th>成绩</th><th>状态</th><th>来源 / 录入人</th></tr></thead><tbody><tr v-for="g in profile.grades" :key="g.source+g.id"><td>{{g.title}}<br><small>{{g.course}}</small><p v-if="g.note">{{g.note}}</p></td><td>{{g.date}}</td><td>{{g.score??'—'}} / {{g.totalScore}}</td><td>{{g.status==='CANCELLED'?'已取消':g.status==='GRADED'?(g.passed?'及格':'未及格'):g.status==='SUBMITTED'?'待判卷':'考试中'}}</td><td>{{g.source==='SYSTEM'?'系统考试':'人工补考'}}<br>{{g.recordedBy||'—'}}<br><small>{{g.recordedAt?new Date(g.recordedAt).toLocaleString('zh-CN'):''}}</small></td></tr></tbody></table></div><p v-if="!profile.grades.length">尚无成绩记录</p></article></template>
</template>
<style scoped>.panel{margin-bottom:18px}.panel h2{font-size:18px}.panel p{line-height:1.8;font-size:13px}.profile-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:20px}.profile-form label{display:grid;gap:8px;font-size:13px}.profile-form input,.profile-form textarea{width:100%;min-width:0;padding:10px;border:1px solid #d5e1e9;border-radius:6px;font:inherit}.wide{grid-column:1/-1}.profile-form button{justify-self:start}summary{cursor:pointer;font-weight:600}.hint{color:#647a8b}td p{max-width:300px;white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:700px){.profile-form{grid-template-columns:1fr}.profile-form button{width:100%}}</style>
